82	  // Request $errors on preview rows for admins; no-op for non-admins.
83	  const previewOutputSettings = useMemo(
84	    () => ({ ...jobSpecificOptions, include_errors: isVersableAdmin }),
85	    [jobSpecificOptions, isVersableAdmin]
