1	// Pure derivation: row + jobStatus → JobItemMetadata. Consumed by the
2	// preview-modal cells (Status / Logs / Actions). No React, no UI imports —
3	// the renderer maps `status` → icon/color separately in row-cells.tsx.
4	
5	import type { JobStatus, LocalJobStatus } from "@/app/jobs/jobs.types";
6	import type { AdminStatusOverride, CauseRecord, JobOutputResponse } from "./output";
7	
8	/** Statuses that mean "job hasn't kicked off any work yet". Anything
9	 *  outside this set counts as "started" — including running, paused,
10	 *  terminal, and scraper-side states like "processing". */
11	const NotStartedStatus = new Set<JobStatus | LocalJobStatus | string>([
12	  "pending",
13	  "incomplete",
14	  "configuring",
15	  "missing",
16	]);
17	
18	/** Derived UI status — superset of `ItemTaskStatus` with four added
19	 *  states the worker doesn't surface directly: `not_started`, `paused`,
20	 *  `deferred_max`, `rerunning`. `rerunning` is BE-signalled
21	 *  (metadata.py synthesizes `$task_status: "rerunning"` when a task has
22	 *  been rerun and is back in a non-terminal state). */
23	export type JobItemStatus =
24	  | "not_started"
25	  | "queued"
26	  | "running"
27	  | "retrying"
28	  | "rerunning"
29	  | "deferred"
30	  | "deferred_max"
31	  | "paused"
32	  | "canceled"
33	  | "failed"
34	  | "completed";
35	
36	export type JobItemStatusGroup = "pending" | "running" | "complete" | "error";
37	
38	export const JobItemStatusList: JobItemStatus[] = [
39	  "not_started",
40	  "queued",
41	  "paused",
42	
43	  "running",
44	  "rerunning",
45	  "retrying",
46	
47	  "deferred",
48	  "deferred_max",
49	
50	  "failed",
51	  "canceled",
52	  "completed",
53	];
54	
55	export type BreakerSnapshot = {
56	  state: "open" | "half_open" | "closed";
57	  module?: string;
58	  etaSeconds?: number;
59	};
60	
61	export type JobItemMetadata = {
62	  /** Single derived state — UI cells switch on this. */
63	  status: JobItemStatus;
64	  /** Truthy when an admin force-status is active. Carries reason + set_at. */
65	  override?: AdminStatusOverride;
66	
67	  retries: number | null;
68	  maxRetries: number | null;
69	  deferCount: number | null;
70	  maxDeferCount: number | null;
71	  /** BE-surfaced count of explicit reruns on the latest task. Drives the
72	   *  "rerunning" badge counter. Null when absent (e.g. fresh task). */
73	  rerunCount: number | null;
74	  breaker?: BreakerSnapshot;
75	
76	  /** Job-level signal. Header-gating uses this to hide cells when the job
77	   *  hasn't started (no items picked up yet). */
78	  hasJobStarted: boolean;
79	  /** Sugar over `status === "paused"`. */
80	  isPaused: boolean;
81	
82	  /** Most-recent-first, capped at 10 BE-side. */
83	  causes: CauseRecord[];
84	  /** Present when BE surfaces it; absent otherwise. */
85	  taskId?: string;
86	};
87	
88	/** Narrow input — the modal already casts `row.$worker` to the typed shape. */
89	export type JobRowForDerive = {
90	  processed?: boolean;
91	  $worker?: JobOutputResponse.ItemWorkerInfoFull;
92	};
93	
94	const numOrNull = (v: unknown): number | null => (typeof v === "number" ? v : null);
95	
96	/**
97	 * Single derivation rule. Precedence (highest first):
98	 *  1. Admin override (sits on top of worker's view)
99	 *  2. Per-row not-started — no `$worker` on the row yet
100	 *  3. Worker-reported terminal states (canceled / failed / processed→completed)
101	 *  4. Paused
102	 *  5. Active intermediate states (deferred_max → deferred → retrying → rerunning → running)
103	 *  6. Default: queued
104	 *
105	 * NOTE on Job.status: BE doesn't reliably progress `Job.status` from
106	 * "pending" → "running" → "completed", so we cannot trust it to decide
107	 * whether the job has actually started. The `$worker` presence on each
108	 * row is the reliable per-row signal. `hasJobStarted` is still exposed
109	 * on the model (for cells that want a job-level hint) — it OR's the
110	 * worker-touched signal so a job with any worker activity counts as
111	 * started even if Job.status is stuck.
112	 */
113	export const deriveJobItemMetadata = (row: JobRowForDerive, jobStatus: JobStatus | LocalJobStatus): JobItemMetadata => {
114	  const worker = row.$worker;
115	  const $w = worker ?? ({} as JobOutputResponse.ItemWorkerInfoFull);
116	  const processed = row.processed === true;
117	  // Combine signals — worker presence implies the job has started for THIS row,
118	  // even if Job.status is stuck at "pending" (BE doesn't reliably progress it).
119	  const hasJobStarted = !!worker || !NotStartedStatus.has(jobStatus);
120	  const override = $w.$admin_status_override;
121	
122	  const retries = numOrNull($w.$retries);
123	  const maxRetries = numOrNull($w.$max_retries);
124	  const deferCount = numOrNull($w.$defer_count);
125	  const maxDeferCount = numOrNull($w.$max_defer_count);
126	  const rerunCount = numOrNull($w.$rerun_count);
127	  const causes = $w?.$cause_records ?? [];
128	  const breaker: BreakerSnapshot | undefined = !$w?.$breaker_state
129	    ? undefined
130	    : {
131	        state: $w.$breaker_state as BreakerSnapshot["state"],
132	        module: $w.$breaker_module,
133	        etaSeconds: $w.$breaker_eta_seconds,
134	      };
135	
136	  const base = {
137	    override,
138	    retries,
139	    maxRetries,
140	    deferCount,
141	    maxDeferCount,
142	    rerunCount,
143	    breaker,
144	    hasJobStarted,
145	    causes,
146	  };
147	
148	  if (override) return { ...base, status: override.status, isPaused: false };
149	
150	  // Per-row signal only — worker hasn't touched this row yet. Don't gate on
151	  // jobStatus: BE doesn't reliably progress Job.status, and once $worker is
152	  // present we trust the worker's view over the job-level field.
153	  if (!worker && !processed) return { ...base, status: "not_started", isPaused: false };
154	
155	  const taskStatus = $w.$task_status;
156	  const isDeferMax = deferCount !== null && maxDeferCount !== null && deferCount >= maxDeferCount;
157	  const isDeferred = !isDeferMax && $w.$breaker_state === "open" && (deferCount ?? 0) > 0;
158	  const isRetrying = retries !== null && retries > 0;
159	
160	  if (taskStatus === "canceled") return { ...base, status: "canceled", isPaused: false };
161	  if (taskStatus === "failed") return { ...base, status: "failed", isPaused: false };
162	  if (processed) return { ...base, status: "completed", isPaused: false };
163	  if (taskStatus === "paused") return { ...base, status: "paused", isPaused: true };
164	
165	  if (isDeferMax) return { ...base, status: "deferred_max", isPaused: false };
166	  if (isDeferred) return { ...base, status: "deferred", isPaused: false };
167	  if (isRetrying) return { ...base, status: "retrying", isPaused: false };
168	  // BE-explicit rerunning marker. Sits BELOW retrying (retry detail is
169	  // more actionable), but ABOVE running/queued (more informative).
170	  if (taskStatus === "rerunning") return { ...base, status: "rerunning", isPaused: false };
171	  if (taskStatus === "running") return { ...base, status: "running", isPaused: false };
172	
173	  return { ...base, status: "queued", isPaused: false };
174	};
175	
176	/** Cast the row's `unknown` $worker to its typed shape, preserving absence:
177	 *  undefined means the worker hasn't touched this row (→ not_started). Field-access
178	 *  callers default to {} locally; deriveJobItemMetadata needs the undefined. */
179	export const getRowWorker = (row: { $worker?: unknown }): JobOutputResponse.ItemWorkerInfoFull | undefined =>
180	  row?.$worker as JobOutputResponse.ItemWorkerInfoFull | undefined;
181	
182	export type StatusCounts<ExcludeAll extends boolean = false> = ExcludeAll extends true
183	  ? Record<JobItemStatus, number>
184	  : Record<JobItemStatus | "all", number>;
185	
186	/** Derive every row's status + per-status counts in one pass (avoids re-filtering N times). */
187	export const groupRowsByStatus = <R extends { processed?: boolean; $worker?: unknown }>(
188	  rows: R[],
189	  jobStatus: JobStatus | LocalJobStatus
190	): { rowStatus: Map<R, JobItemStatus>; counts: StatusCounts } => {
191	  const rowStatus = new Map<R, JobItemStatus>();
192	  const counts: StatusCounts = {
193	    all: rows.length,
194	    not_started: 0,
195	    queued: 0,
196	    running: 0,
197	    retrying: 0,
198	    rerunning: 0,
199	    deferred: 0,
200	    deferred_max: 0,
201	    paused: 0,
202	    canceled: 0,
203	    failed: 0,
204	    completed: 0,
205	  };
206	  for (const row of rows) {
207	    const status = deriveJobItemMetadata({ processed: row.processed, $worker: getRowWorker(row) }, jobStatus).status;
208	    rowStatus.set(row, status);
209	    counts[status] += 1;
210	  }
211	  return { rowStatus, counts };
212	};
