72	
73	  const queryKey = QueryKeys.GetJobOutput(jobId).concat(
74	    options.fabOptions.mode,
75	    options.fabOptions.delimiter || "number",
76	    options.tabToShow || "default-tab"
77	  );
78	
79	  const fn = useMemo(() => (customItems?.length ? getJobOutputPost : getJobOutput), [customItems?.length]);
80	
81	  const {
82	    data: outputResponse,
83	    isLoading,
84	    isFetching,
85	    isPending,
86	    refetch: refetchOutput,
87	    dataUpdatedAt,
88	  } = useQ({
89	    staleTime: 5_000,
90	    error: {
91	      toast: {
92	        // Render the backend's structured JobOutputError envelope into a user-facing
93	        // sentence; fall back to the generic API error for non-job-output failures.
94	        message: (err) => formatJobOutputError(err, `Couldn't load preview for this job. Please try again.`),
95	        options: {
96	          duration: -1,
97	        },
98	      },
99	    },
100	    placeholderData: keepPreviousData,
101	    enabled: !initialDisabled,
102	    queryKey,
103	    ...observerOptions,
104	
105	    queryFn: async () =>
106	      await fn<JobOutputResponse.PreviewWithMetadata>({
107	        jobId,
108	        args: {
109	          custom_items: customItems,
110	          custom_job_config_data: customJobConfig,
111	          // Fetch all items once, filter locally for snappier UX.
112	          additionalQueryParams: tabToShow && tabToShow !== DefaultTab ? { file_tab: tabToShow } : {},
113	          output_settings: {
114	            fallback_input_values: true,
115	            include_metadata: true,
116	            fab_options: fabOptions,
117	            items_skip: 0,
118	            items_limit: MaxJobPreviewRowLimit,
119	            ...outputSettings,
120	          },
121	          paginationQueryParams: {
122	            // Local pagination — file rows < 5k. Revisit if perf becomes an issue.
123	            return_all: false,
124	          },
125	        },
126	      }).then(({ data = [], metadata, ...resp }) => ({
127	        ...resp,
128	        data: data,
129	        metadata: {
130	          total: metadata.total ?? 100,
131	          limit: metadata.limit ?? 10,
132	          skip: metadata.skip ?? 0,
133	          contentType: metadata.contentType ?? "application/json",
134	          s3Url: metadata.s3Url ?? "",
135	          s3UrlExpires: metadata.s3UrlExpires ?? 0,
136	          outputFileTabs: (metadata.outputFileTabs || "").split(";") || [],
137	          dataSource: metadata.dataSource || "unknown",
138	          transformFns: metadata.transformFns || [],
139	        },
140	      })),
141	  });
142	
143	  const {
144	    outputRows = [],
145	    metadata,
146	    allRows = [],
147	    statusCounts,
148	  } = useMemo(() => {
149	    const allRows = outputResponse?.data ?? [];
150	    // One pass over all rows: derive each row's real status, count per status,
151	    // and slice the active filter — replaces the old processed-boolean split.
152	    const { rowStatus, counts } = groupRowsByStatus(allRows, jobStatus);
153	    const rows =
154	      itemStatusFilter.length === 0
155	        ? allRows
156	        : allRows.filter((r) => rowStatus.get(r) && itemStatusFilter.includes(rowStatus.get(r)!));
157	    return {
158	      outputRows: rows,
159	      allRows,
160	      statusCounts: counts,
161	      metadata: outputResponse?.metadata ?? {
162	        total: 100,
163	        limit: 10,
164	        skip: 0,
165	        contentType: "application/json",
166	        outputFileTabs: [],
167	        dataSource: "unknown",
168	      },
169	    };
170	  }, [outputResponse, itemStatusFilter, jobStatus]);
171	
172	  // Auto-select the first tab once tab metadata arrives.
173	  useEffect(() => {
174	    if (tabToShow) return;
175	    if (!metadata?.outputFileTabs?.length) return;
176	    console.log("setTabToShow", metadata?.outputFileTabs?.[0]);
177	    setTabToShow(metadata.outputFileTabs[0] ?? DefaultTab);
178	  }, [metadata?.outputFileTabs, tabToShow]);
179	
180	  return {
181	    data: {
182	      outputRows,
183	      metadata,
184	      allRows,
185	      statusCounts,
186	      refetchOutput,
187	    },
188	    flags: {
189	      isLoading,
190	      isFetching,
191	      isPending,
192	      dataUpdatedAt,
193	    },
194	    options,
195	    setOptions,
196	  };
197	};
